export function enforceQueryBudget({estimatedRows=0,estimatedBytes=0,estimatedCpuMs=0,safety=false},{maxRows=10000,maxBytes=5e6,maxCpuMs=1500}={}){if(safety)return {allow:true,reason:'SAFETY_QUERY',degrade:false};if(estimatedRows>maxRows||estimatedBytes>maxBytes||estimatedCpuMs>maxCpuMs)return {allow:false,reason:'QUERY_BUDGET_EXCEEDED',suggestion:'reduce_space_time_or_resolution'};return {allow:true,reason:'WITHIN_QUERY_BUDGET',degrade:false}}
